sources.app.tsx:
// The code of the frame's scenes on its own screen (docs/code-editor.md): every
// scene as files (scene.json, each app's files, each code node's code), each
// file one colored text to scroll through and type into, and the control
// plane's AI to ask for a new scene or a change to the one open. Everything
// goes through frameos.code, which needs the "code" permission (installing the
// scene is the owner's yes) and the frame's settings allowed on its screen.
//
// Where it is (the scene open, the file, what it asked) is the private `spot`
// field, kept on disk. The files with their edits, what is being typed, where
// each file is scrolled to and the request are kept with frameos.remember, so
// they outlast an interpreter the frame let go. The scene settings' Code
// button opens it on a scene through the public field `open`.

const DRAFT = '\u0001draft' // the work's key for the AI's scene: no scene id has a \u0001

const WORDS = {
  no_plane: 'This frame has no control plane to ask: link it to a FrameOS backend or FrameOS Cloud.',
  ai_unavailable: "The control plane has no AI to ask (its OpenAI key, or the account's AI budget).",
  needs_owner:
    'This scene asks for more than the saved one could do (permissions or service keys). Install it from the control plane, where those are granted.',
  panel_locked: "The control plane has turned the settings on this frame's screen off.",
  rate_limited: 'Too many requests for now. Try again in a while.',
  plane_update_required: 'The control plane needs a newer FrameOS for this.',
  plane_unavailable: 'The control plane did not answer.',
  invalid_scene: 'That is not a scene this frame can hold.',
  invalid_layout: 'That layout is not one a frame can wear: a layout needs exactly one <yield />.',
  scene_requires_compilation: 'That scene needs compiling, which only a deploy does.',
  timeout: 'The AI did not finish in time.',
  no_scene: 'The AI did not deliver a scene.',
  render_failed: "The AI's scene did not render on this frame.",
  render_out_of_memory: "The AI's scene needs more memory than this frame has.",
  empty_prompt: 'Say what the scene should do first.',
  invalid_answer: 'The control plane answered with something that is not a scene.',
  no_room: 'The frame has no memory to spare for that answer.',
  failed: 'That did not work.',
}
const say = (code) => WORDS[code] || `That did not work (${code}).`

const kept = (key, empty) => {
  const value = frameos.recall(key)
  return value === undefined || value === null ? empty : value
}

// ----------------------------------------------------------------- the code

function code(op, arg) {
  try {
    return { ok: true, value: frameos.code(op, arg) }
  } catch (e) {
    return { ok: false, why: String((e && e.message) || e).replace(/^frameos\.code: /, '') }
  }
}

// ---------------------------------------------------------------- the files

// A scene as files: scene.json without its apps and its code nodes' code,
// then `<app>/<file>` for every app's files and `code/<node>.js` for every
// code node's code.
export function filesOf(scene) {
  const files = {}
  const order = ['scene.json']
  const base = {}
  for (const key of Object.keys(scene)) if (key !== 'apps') base[key] = scene[key]
  base.nodes = (Array.isArray(scene.nodes) ? scene.nodes : []).map((node) => {
    if (!node || node.type !== 'code' || !node.data || typeof node.data.codeJS !== 'string') return node
    const data = { ...node.data }
    files[`code/${node.id}.js`] = data.codeJS
    order.push(`code/${node.id}.js`)
    delete data.codeJS
    return { ...node, data }
  })
  files['scene.json'] = JSON.stringify(base, null, 2)
  const apps = scene.apps && typeof scene.apps === 'object' ? scene.apps : {}
  for (const name of Object.keys(apps)) {
    const sources = (apps[name] && apps[name].sources) || {}
    for (const file of Object.keys(sources)) {
      if (typeof sources[file] !== 'string') continue
      files[`${name}/${file}`] = sources[file]
      order.push(`${name}/${file}`)
    }
  }
  // Code nodes after the apps: an app is what a scene is mostly made of.
  const codes = order.filter((f) => f.startsWith('code/'))
  return { files, order: [...order.filter((f) => !f.startsWith('code/')), ...codes] }
}

// The files back into the scene they came from: { scene } or { error }.
export function sceneOf(original, files) {
  let scene
  try {
    scene = JSON.parse(files['scene.json'])
  } catch (e) {
    return { error: `scene.json: ${String((e && e.message) || e)}` }
  }
  if (!scene || typeof scene !== 'object' || Array.isArray(scene)) return { error: 'scene.json: not an object' }
  const apps = {}
  const was = original.apps && typeof original.apps === 'object' ? original.apps : {}
  for (const name of Object.keys(was)) {
    const app = { ...was[name], sources: { ...((was[name] && was[name].sources) || {}) } }
    for (const file of Object.keys(app.sources)) {
      const text = files[`${name}/${file}`]
      if (typeof text === 'string') app.sources[file] = text
    }
    const config = app.sources['config.json']
    if (typeof config === 'string') {
      let parsed
      try {
        parsed = JSON.parse(config)
      } catch (e) {
        return { error: `${name}/config.json: ${String((e && e.message) || e)}` }
      }
      // What the scene carries beside the files follows config.json.
      for (const key of Object.keys(app)) {
        if (key !== 'sources' && parsed && key in parsed) app[key] = parsed[key]
      }
    }
    apps[name] = app
  }
  if (Object.keys(was).length) scene.apps = apps
  scene.nodes = (Array.isArray(scene.nodes) ? scene.nodes : []).map((node) => {
    const text = node && files[`code/${node.id}.js`]
    return typeof text === 'string' ? { ...node, data: { ...node.data, codeJS: text } } : node
  })
  return { scene }
}

// What no frame takes (docs/code-editor.md), said before a save: the plane
// and a frame with no plane would refuse it too. "" when it may go.
export function refusalOf(scene) {
  const id = scene && scene.id
  if (typeof id !== 'string' || !id || id.length > 127 || id.startsWith('system/')) return 'invalid_scene'
  const execution = scene.settings && scene.settings.execution
  return execution && execution !== 'interpreted' ? 'scene_requires_compilation' : ''
}

// What is being worked on: the scene (or the draft) as it was read, its files
// with the edits, and which files changed. Kept here as well as remembered: a
// render reads it, and a recall parses all of it.
let held = null
const setWork = (work) => {
  held = work
  frameos.remember('work', work)
}
// The work let go: another scene opened, a draft dropped, or a save to read
// back from the frame (which keeps where each file was scrolled to).
const dropWork = (keepPlaces = false) => {
  setWork(null)
  current = null
  frameos.remember('typing', null)
  if (!keepPlaces) {
    scrolls = {}
    frameos.remember('scrolls', null)
  }
}
function workFor(key) {
  if (!held) {
    held = kept('work', null)
    // Typed before the interpreter was let go, and not folded back: folded now.
    const typing = kept('typing', null)
    if (held && typing && typing.key === held.key && typeof held.files[typing.file] === 'string') {
      const lines = held.files[typing.file].split('\n')
      lines.splice(typing.a, typing.span, ...String(typing.value).split('\n'))
      held.files[typing.file] = lines.join('\n')
      if (!held.changed.includes(typing.file)) held.changed.push(typing.file)
      setWork(held)
    }
    frameos.remember('typing', null)
  }
  if (held && held.key === key) return held
  const read = key === DRAFT ? code('draft') : code('source', key)
  if (!read.ok) return { key, error: read.why }
  if (!read.value) return { key, error: key === DRAFT ? 'The draft is gone.' : 'This frame does not hold that scene.' }
  const { files, order } = filesOf(read.value)
  const fresh = { key, original: read.value, files, order, changed: [] }
  setWork(fresh)
  return fresh
}

// ----------------------------------------------------------------- the spot

function readSpot(app) {
  let spot = app.state.spot
  if (typeof spot === 'string') {
    try {
      spot = JSON.parse(spot)
    } catch (e) {
      spot = null
    }
  }
  return spot && typeof spot === 'object' ? spot : {}
}
const saveSpot = (spot) => frameos.setState('spot', spot)
// A change of where it is, from a handler: kept at once, since the next
// render reads the field again.
const set = (spot, change) => {
  Object.assign(spot, change)
  saveSpot(spot)
}

// Opened from the scene settings' Code button, on that scene.
function opened(app, spot) {
  const open = app.state.open
  if (typeof open !== 'string' || !open) return
  frameos.setState('open', '')
  if (spot.id === open && !spot.draft) return
  set(spot, { view: 'code', id: open, draft: false, file: 'scene.json', note: '' })
  dropWork()
}

// ----------------------------------------------------------------- the look
//
// A code editor's workbench, after VS Code's Dark+: an activity bar, the
// explorer with the scenes by category or the scene's files, a tab bar with
// the editor's actions and breadcrumbs over the code, and a status bar. No
// title bar: a desktop's window has its own, and the activity bar is the way
// back to the scenes. Text is the size other windows
// use (13 px, the frame's render scale makes it bigger on a big screen), and
// the code is colored by kind, in Cascadia Mono where the frame has it in its
// fonts (a Pi), else in its own face. Lines are not wrapped, as in VS Code: a
// long one scrolls sideways. A narrow screen drops
// the activity bar and the explorer for a select of the files; e-paper and a
// grey panel are black on white, the code uncolored.

const DARK = {
  activity: 'bg-[#333333]',
  activityOn: 'text-white border-l-2 border-white',
  activityOff: 'text-[#858585] active:text-white border-l-2 border-[#333333]',
  side: 'bg-[#252526] text-[#cccccc]',
  sideHead: 'text-[#bbbbbb]',
  row: 'active:bg-[#2a2d2e]',
  rowOn: 'bg-[#37373d] text-white',
  tabs: 'bg-[#252526]',
  tab: 'bg-[#1e1e1e] text-white',
  crumbs: 'bg-[#1e1e1e] text-[#a9a9a9]',
  editor: 'bg-[#1e1e1e] text-[#d4d4d4]',
  gutter: 'text-[#858585]',
  status: 'bg-[#007acc] text-white',
  statusDraft: 'bg-[#68217a] text-white',
  button: 'bg-[#3a3d41] text-white active:bg-[#45494e]',
  primary: 'bg-[#0e639c] text-white active:bg-[#1177bb]',
  off: 'text-[#6f6f6f]',
  field: 'bg-[#313131] text-[#cccccc] border border-[#3c3c3c] focus:border-[#007fd4]',
  link: 'text-[#3794ff]',
  dim: 'text-[#9d9d9d]',
  changed: 'text-[#e2c08d]',
  toast: 'bg-[#252526] text-[#cccccc] border border-[#454545]',
  info: 'bg-[#252526] text-[#cccccc] border-l-2 border-[#3794ff]',
  line: 'border-[#2b2b2b]',
}
const INK = {
  activity: 'bg-white border-r-2 border-black',
  activityOn: 'bg-black text-white',
  activityOff: 'text-black',
  side: 'bg-white text-black border-r-2 border-black',
  sideHead: 'text-black font-bold',
  row: '',
  rowOn: 'bg-black text-white',
  tabs: 'bg-white border-b-2 border-black',
  tab: 'bg-white text-black font-bold',
  crumbs: 'bg-white text-black',
  editor: 'bg-white text-black',
  gutter: 'text-black',
  status: 'bg-black text-white',
  statusDraft: 'bg-black text-white',
  button: 'bg-white text-black border-2 border-black',
  primary: 'bg-black text-white',
  off: 'text-black opacity-40',
  field: 'bg-white text-black border-2 border-black',
  link: 'text-black underline',
  dim: 'text-black',
  changed: 'text-black font-bold',
  toast: 'bg-white text-black border-2 border-black',
  info: 'bg-white text-black border-l-4 border-black',
  line: 'border-black',
}

const MONO = 'font-[Cascadia_Mono]'

// What a kind of token is drawn in (Dark+).
const COLORS = {
  k: 'text-[#569cd6]', // const, function, true
  c: 'text-[#c586c0]', // return, if, import
  s: 'text-[#ce9178]', // strings
  n: 'text-[#b5cea8]', // numbers
  m: 'text-[#6a9955]', // comments
  f: 'text-[#dcdcaa]', // a function called
  t: 'text-[#4ec9b0]', // a type, a component
  v: 'text-[#9cdcfe]', // a variable, a JSON key
  p: 'text-[#d4d4d4]', // the rest
}

function lookOf(app, context) {
  const ink = app.frame.paper === true || app.frame.color === false
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const width = (context && context.imageWidth) || (turned ? app.frame.height : app.frame.width)
  const height = (context && context.imageHeight) || (turned ? app.frame.width : app.frame.height)
  const size = 13
  return {
    ink,
    width,
    height,
    size,
    c: ink ? INK : DARK,
    wide: width >= 600,
    rowH: 19, // VS Code's line height for 13 px
    tabH: 35,
    statusH: 22,
    activityW: 44,
    sideW: Math.round(Math.min(260, Math.max(170, width * 0.24))),
  }
}

const Icon = ({ d, size = 22, stroke = false }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" className={`shrink-0 w-[${size}px] h-[${size}px]`}>
    {stroke ? (
      <path d={d} fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" />
    ) : (
      <path d={d} fill="currentColor" />
    )}
  </svg>
)
const FILES_ICON = 'M13.5 3H6.5a1.5 1.5 0 0 0-1.5 1.5v15A1.5 1.5 0 0 0 6.5 21h11a1.5 1.5 0 0 0 1.5-1.5V8.5zM13.5 3v5.5H19'
const SCENES_ICON = 'M4 5h16M4 10h16M4 15h10M4 20h7'
const AI_ICON = 'M12 2.5l2.1 6.4 6.4 2.1-6.4 2.1L12 19.5l-2.1-6.4L3.5 11l6.4-2.1zM19 16l.9 2.1L22 19l-2.1.9L19 22l-.9-2.1L16 19l2.1-.9z'
const OPEN = 'M7 10l5 5 5-5'

function Button({ look, label, onClick, primary = false, off = false }) {
  return (
    <div
      className={`shrink-0 flex items-center justify-center h-[22px] px-[10px] rounded-[2px] text-[12px] whitespace-nowrap ${
        off ? look.c.off : primary ? look.c.primary : look.c.button
      }`}
      onClick={off ? undefined : onClick}
    >
      {label}
    </div>
  )
}

// The activity bar: the scenes, the files, the AI.
function ActivityBar({ look, spot, facts, open }) {
  const item = (on, d, onClick, stroke = true) => (
    <div className={`flex items-center justify-center w-[${look.activityW}px] h-[44px] ${on ? look.c.activityOn : look.c.activityOff}`} onClick={onClick}>
      <Icon d={d} stroke={stroke} size={22} />
    </div>
  )
  return (
    <div className={`shrink-0 flex flex-col w-[${look.activityW}px] ${look.c.activity}`}>
      {item(spot.view === 'list', SCENES_ICON, () => set(spot, { view: 'list', note: '' }))}
      {open ? item(spot.view === 'code', FILES_ICON, () => set(spot, { view: 'code', note: '' })) : null}
      {facts.ask ? item(spot.view === 'ask', AI_ICON, () => set(spot, { view: 'ask', note: '' }), false) : null}
    </div>
  )
}

const SideHead = ({ look, text }) => (
  <div className={`shrink-0 flex items-center h-[35px] px-[20px] text-[11px] ${look.c.sideHead}`}>{text}</div>
)

// A row of the explorer: a scene, a folder or a file.
function Row({ look, depth = 0, on = false, label, badge, icon = null, color, chevron = false, mark = '', onClick }) {
  return (
    <div
      className={`shrink-0 flex items-center gap-[6px] h-[22px] pl-[${8 + depth * 12}px] pr-[10px] text-[13px] ${on ? look.c.rowOn : look.c.row}`}
      onClick={onClick}
    >
      {chevron ? <Icon d={OPEN} stroke size={14} /> : <span className={`shrink-0 w-[14px]`} />}
      {icon}
      {badge ? <span className={`shrink-0 text-[10px] font-bold ${look.ink ? '' : color || ''}`}>{badge}</span> : null}
      <span className={`flex-1 min-w-0 truncate ${on ? '' : color && !badge ? color : ''}`}>{label}</span>
      {mark ? <span className={`shrink-0 text-[12px] ${on ? '' : color}`}>{mark}</span> : null}
    </div>
  )
}

// What kind of file it is: its badge, its color, its language.
function kindOf(file) {
  const ext = (file.match(/\.([a-z]+)$/i) || ['', ''])[1].toLowerCase()
  if (ext === 'json') return { badge: '{}', color: 'text-[#cbcb41]', lang: 'JSON' }
  if (ext === 'tsx') return { badge: 'TSX', color: 'text-[#519aba]', lang: 'TypeScript JSX' }
  if (ext === 'ts') return { badge: 'TS', color: 'text-[#519aba]', lang: 'TypeScript' }
  if (ext === 'jsx') return { badge: 'JSX', color: 'text-[#cbcb41]', lang: 'JavaScript JSX' }
  if (ext === 'js') return { badge: 'JS', color: 'text-[#cbcb41]', lang: 'JavaScript' }
  if (ext === 'nim') return { badge: 'NIM', color: 'text-[#e8c33f]', lang: 'Nim' }
  return { badge: '·', color: '', lang: 'Plain Text' }
}

// The scene's files as a tree: scene.json, then a folder per app and `code`.
function treeOf(order) {
  const rows = []
  let folder = null
  for (const file of order) {
    const at = file.indexOf('/')
    const dir = at < 0 ? '' : file.slice(0, at)
    if (dir && dir !== folder) rows.push({ folder: dir })
    folder = dir
    rows.push({ file, name: at < 0 ? file : file.slice(at + 1), depth: dir ? 1 : 0 })
  }
  return rows
}

function Explorer({ look, spot, work, file, title }) {
  return (
    <div className={`shrink-0 flex flex-col w-[${look.sideW}px] min-h-0 ${look.c.side}`}>
      <SideHead look={look} text="EXPLORER" />
      <div className={`shrink-0 flex items-center h-[22px] px-[8px] text-[11px] font-bold ${look.c.sideHead}`}>
        <Icon d={OPEN} stroke size={14} />
        <span className="min-w-0 truncate pl-[2px]">{String(title).toUpperCase()}</span>
      </div>
      <div className="flex flex-col flex-1 min-h-0 overflow-y-auto">
        {treeOf(work.order).map((row) =>
          row.folder ? (
            <Row look={look} depth={1} label={row.folder} chevron />
          ) : (
            <Row
              look={look}
              depth={row.depth + 1}
              on={row.file === file}
              label={row.name}
              mark={work.changed.includes(row.file) ? 'M' : ''}
              badge={kindOf(row.file).badge}
              color={work.changed.includes(row.file) ? look.c.changed : kindOf(row.file).color}
              onClick={() => set(spot, { file: row.file })}
            />
          ),
        )}
      </div>
    </div>
  )
}

// A list of scenes in groups by their category (`category` on each entry of
// app.frame.scenes: the scene's settings.category, its name, "Photos"): one
// group under each name, the groups by name whatever the case, and the scenes
// with none (or "Other") last, as Other. Where no scene has one, one group with
// no title: the list as it always was. Every desktop with a list of scenes has
// this same function.
function grouped(scenes) {
  const nameOf = (scene) => {
    const name = typeof scene.category === 'string' ? scene.category.trim() : ''
    return name.toLowerCase() === 'other' ? '' : name
  }
  const names = []
  for (const scene of scenes) {
    const name = nameOf(scene)
    if (name && !names.includes(name)) names.push(name)
  }
  if (!names.length) return [{ title: null, scenes }]
  names.sort((a, b) => {
    const x = a.toLowerCase()
    const y = b.toLowerCase()
    return x < y ? -1 : x > y ? 1 : a < b ? -1 : a > b ? 1 : 0
  })
  const groups = names.map((title) => ({ title, scenes: scenes.filter((scene) => nameOf(scene) === title) }))
  const rest = scenes.filter((scene) => !nameOf(scene))
  if (rest.length) groups.push({ title: 'Other', scenes: rest })
  return groups
}
// A scene's own icon (`icon` on its entry of app.frame.scenes, docs/scene-icons.md):
// one path in a 24 box, filled in the color of the text around it, `size` wide
// and high (a length); null where the scene has none, and the desktop draws its
// own. Every desktop that draws its scenes' icons has this same function.
function ownIcon(scene, size) {
  if (!scene || typeof scene.icon !== 'string' || !scene.icon) return null
  return (
    <svg viewBox="0 0 24 24" className={`shrink-0 w-[${size}] h-[${size}]`}>
      <path d={scene.icon} fill="currentColor" />
    </svg>
  )
}

// The frame's scenes as the explorer's tree: a folder per category.
function SceneList({ app, look, spot, onOpen }) {
  const list = (Array.isArray(app.frame.scenes) ? app.frame.scenes : []).filter((s) => s && s.id)
  const rows = []
  for (const group of grouped(list)) {
    if (group.title) rows.push(<Row look={look} depth={0} label={group.title} chevron />)
    for (const scene of group.scenes) {
      rows.push(
        <Row
          look={look}
          depth={group.title ? 1 : 0}
          on={scene.id === spot.id}
          label={scene.name || scene.id}
          icon={ownIcon(scene, '14px') || <span className="shrink-0 w-[14px]" />}
          onClick={() => onOpen(scene.id)}
        />,
      )
    }
  }
  return (
    <div className="flex flex-col flex-1 min-h-0 overflow-y-auto">
      {rows}
      {list.length ? null : <div className={`p-[12px] text-[13px] ${look.c.dim}`}>This frame lists no scenes here.</div>}
    </div>
  )
}

function StatusBar({ look, left, right, draft }) {
  return (
    <div className={`shrink-0 flex items-center gap-[14px] h-[${look.statusH}px] px-[10px] text-[12px] ${draft ? look.c.statusDraft : look.c.status}`}>
      {left.map((text) => (
        <span className="shrink-0 whitespace-nowrap">{text}</span>
      ))}
      <span className="flex-1" />
      {right.map((text) => (
        <span className="shrink-0 whitespace-nowrap">{text}</span>
      ))}
    </div>
  )
}

// A notification over the bottom right corner; a tap puts it away.
function Toast({ look, spot }) {
  if (!spot.note) return null
  const width = Math.min(380, look.width - 24)
  return (
    <div
      className={`absolute right-[12px] bottom-[${look.statusH + 12}px] w-[${width}px] flex items-start gap-[8px] p-[10px] text-[13px] leading-snug ${look.c.toast}`}
      onClick={() => set(spot, { note: '' })}
    >
      <span className="flex-1 min-w-0">{spot.note}</span>
      <span className={look.c.dim}>✕</span>
    </div>
  )
}

// ----------------------------------------------------------------- the code

const KEYWORDS = new Set(
  'const let var function class new typeof instanceof in of this null undefined true false async void delete extends static get set interface type enum as'.split(' '),
)
const CONTROL = new Set('return if else for while do switch case break continue throw try catch finally import export from default await yield'.split(' '))
const TOKEN = /(\/\/.*)|(\/\*.*?(?:\*\/|$))|("(?:[^"\\]|\\.)*"?|'(?:[^'\\]|\\.)*'?|`(?:[^`\\]|\\.)*`?)|(\b\d[\d_]*(?:\.\d+)?\b)|([A-Za-z_$][\w$]*)|(\s+)|(.)/g

// One line as tokens [{t, k}], and whether a block comment is still open after it.
export function tokensOf(line, lang, inComment) {
  const out = []
  let at = 0
  if (inComment) {
    const end = line.indexOf('*/')
    if (end < 0) return { tokens: [{ t: line, k: 'm' }], open: true }
    out.push({ t: line.slice(0, end + 2), k: 'm' })
    at = end + 2
  }
  const json = lang === 'JSON'
  const plain = lang === 'Plain Text'
  let open = false
  TOKEN.lastIndex = at
  let m
  let prev = ''
  while (at < line.length && (m = TOKEN.exec(line))) {
    at = TOKEN.lastIndex
    const t = m[0]
    let k = 'p'
    if (plain) k = 'p'
    else if (m[1] && !json) k = 'm'
    else if (m[2] && !json) {
      k = 'm'
      open = !t.endsWith('*/') || t.length < 4
    } else if (m[3]) k = json && /^\s*:/.test(line.slice(at)) ? 'v' : 's'
    else if (m[4]) k = 'n'
    else if (m[5]) {
      if (json) k = KEYWORDS.has(t) ? 'k' : 'p'
      else if (CONTROL.has(t)) k = 'c'
      else if (KEYWORDS.has(t)) k = 'k'
      else if (prev === '<' || prev === '</') k = /^[A-Z]/.test(t) ? 't' : 'k'
      else if (/^\s*\(/.test(line.slice(at))) k = 'f'
      else if (/^[A-Z]/.test(t)) k = 't'
      else k = 'v'
    }
    if (!/^\s+$/.test(t)) prev = prev === '<' && t === '/' ? '</' : t
    const last = out[out.length - 1]
    if (last && last.k === k) last.t += t
    else out.push({ t, k })
  }
  return { tokens: out, open }
}

// ------------------------------------------------------------ the file open
//
// A file is one box that scrolls, as tall as all its lines, holding only the
// lines around where it is scrolled to (the screen showing and a screen above
// and below) as one <textarea>: colored by the spans inside it, typed into
// where it is tapped, its lines never wrapped (it scrolls sideways), the line
// numbers beside it. Spacers stand in for the lines above and below, and
// scrolling slides the window (onScroll). A window changes at one end at a
// time, so the field keeps its caret on the text it was in (docs/jsx-ui.md
// "Fields and the keyboard"), and a 2,000-line app is a hundred lines to lay
// out on an ESP32.

const ROW = 19 // VS Code's line height for 13 px
const PAD = 4 // above the first line

// The file open: its lines (the truth while it is typed into, folded back into
// the work's text when the window moves), the window [a, b) in the field, how
// many lines of the folded text the window stood for (`span`), whether it was
// typed into since (`dirty`), and the lines' tokens as far as they were read.
let current = null

// Where each file was scrolled to, by the work and the file.
let scrolls = null
const scrollsKept = () => scrolls || (scrolls = kept('scrolls', {}))

function docFor(work, file) {
  if (current && current.key === work.key && current.file === file) return current
  if (current && current.key === work.key) fold(work)
  const lines = String(work.files[file] || '').split('\n')
  current = { key: work.key, file, lines, a: -1, b: -1, span: 0, dirty: false, opens: [false], toks: [], ver: 0 }
  return current
}

// What was typed, into the work's text (before the window moves, a save, an
// ask, another file).
function fold(work) {
  if (!current || !current.dirty || current.key !== work.key) return
  work.files[current.file] = current.lines.join('\n')
  if (!work.changed.includes(current.file)) work.changed.push(current.file)
  current.dirty = false
  setWork(work)
  frameos.remember('typing', null)
}

// The window for the line at the top of the screen and a screen of `fit`
// lines: a screen above it and below it. A window that does not reach that far
// grows at one end; one far longer than it shrinks at the other; one with
// nothing in common with it (a jump) is set anew.
function slide(work, doc, first, fit) {
  const n = doc.lines.length
  const want = [Math.max(0, first - fit), Math.min(n, first + 2 * fit + 1)]
  let { a, b } = doc
  if (a < 0 || b > n || want[1] <= a || want[0] >= b) [a, b] = want
  else if (want[0] < a) a = want[0]
  else if (want[1] > b) b = want[1]
  else if (b - a > 6 * fit) {
    if (first - a > b - first - fit) a = want[0]
    else b = want[1]
  }
  if (a === doc.a && b === doc.b) return
  fold(work)
  Object.assign(doc, { a, b, span: b - a })
  doc.ver++
}

// Line i's tokens, and whether a block comment is open at its start: read in
// order from the file's first line once, kept until an edit above them.
function tokensAt(doc, i, lang) {
  while (doc.opens.length <= i) {
    const j = doc.opens.length - 1
    const read = tokensOf(doc.lines[j], lang, doc.opens[j])
    doc.toks[j] = read.tokens
    doc.opens.push(read.open)
  }
  if (!doc.toks[i]) doc.toks[i] = tokensOf(doc.lines[i], lang, doc.opens[i]).tokens
  return doc.toks[i]
}

// What the field holds, colored: the tokens of the window's lines as spans
// (the rest as text), the same render after render until it changes.
function colored(doc, lang, look) {
  if (look.ink || lang === 'Plain Text') return null
  if (doc.shown && doc.shown.ver === doc.ver) return doc.shown.nodes
  const nodes = []
  for (let i = doc.a; i < doc.b; i++) {
    for (const token of tokensAt(doc, i, lang)) {
      nodes.push(token.k === 'p' ? token.t : <span className={COLORS[token.k]}>{token.t}</span>)
    }
    if (i < doc.b - 1) nodes.push('\n')
  }
  doc.shown = { ver: doc.ver, nodes }
  return nodes
}

// The field typed into: its lines in place of the window's.
export function typed(work, doc, text) {
  const lines = String(text).split('\n')
  doc.lines.splice(doc.a, doc.b - doc.a, ...lines)
  doc.b = doc.a + lines.length
  doc.opens.length = Math.min(doc.opens.length, doc.a + 1)
  doc.toks.length = Math.min(doc.toks.length, doc.a)
  doc.dirty = true
  doc.ver++
  frameos.remember('typing', { key: doc.key, file: doc.file, a: doc.a, span: doc.span, value: String(text) })
  if (!work.changed.includes(doc.file)) {
    work.changed.push(doc.file)
    setWork(work)
  }
}

// ---------------------------------------------------------------- the pages

// Nothing open: the frame's scenes, and a start for a new one.
function Home({ app, look, spot, facts, asking }) {
  const openScene = (id) => {
    set(spot, { view: 'code', id, draft: false, file: 'scene.json', note: '' })
    dropWork()
  }
  const welcome = (
    <div className={`flex flex-col flex-1 min-w-0 gap-[6px] p-[${look.wide ? 40 : 16}px] ${look.c.editor}`}>
      <span className="text-[26px] font-light">Code editor</span>
      <span className={`text-[14px] ${look.c.dim}`}>The code of this frame's scenes</span>
      <span className="pt-[18px] text-[15px]">Start</span>
      {facts.ask ? (
        <div className={`flex items-center gap-[6px] text-[13px] ${look.c.link}`} onClick={() => set(spot, { view: 'ask', id: '', draft: false, note: '' })}>
          <Icon d={AI_ICON} size={14} />
          <span>New scene with AI</span>
        </div>
      ) : (
        <span className={`text-[13px] ${look.c.dim}`}>A frame with a control plane can ask its AI for scenes.</span>
      )}
      <span className="pt-[14px] text-[15px]">Open</span>
      {look.wide ? (
        <span className={`text-[13px] ${look.c.dim}`}>Pick a scene in the explorer to read its files and change them.</span>
      ) : (
        <SceneList app={app} look={look} spot={spot} onOpen={openScene} />
      )}
    </div>
  )
  const list = Array.isArray(app.frame.scenes) ? app.frame.scenes : []
  return (
    <div className="flex flex-col flex-1 min-h-0">
      <div className="flex flex-1 min-h-0">
      {look.wide ? <ActivityBar look={look} spot={spot} facts={facts} open={false} /> : null}
      {look.wide ? (
        <div className={`shrink-0 flex flex-col w-[${look.sideW}px] min-h-0 ${look.c.side}`}>
          <SideHead look={look} text="SCENES" />
          <SceneList app={app} look={look} spot={spot} onOpen={openScene} />
        </div>
      ) : null}
      {asking ? <Ask look={look} spot={spot} facts={facts} work={null} /> : welcome}
      </div>
      <StatusBar look={look} left={[`${list.length} scene${list.length === 1 ? '' : 's'}`]} right={[facts.busy === 'ask' ? 'Asking the AI…' : facts.previewOnly ? 'Read only in the preview' : '']} />
    </div>
  )
}

// The request to the AI: a new scene, or a change to the one open.
function Ask({ look, spot, facts, work }) {
  const prompt = kept('prompt', '')
  const busy = facts.busy === 'ask'
  const changing = !!(spot.id || spot.draft)
  const send = () => {
    const text = kept('prompt', '').trim()
    if (!text) return set(spot, { note: say('empty_prompt') })
    const args = { prompt: text }
    if (changing && work && !work.error) {
      fold(work)
      const built = sceneOf(work.original, work.files)
      if (built.error) return set(spot, { note: built.error })
      args.scene = built.scene
    }
    const r = code('ask', args)
    set(spot, r.ok ? { asking: true, note: '' } : { note: r.why })
  }
  return (
    <div className={`flex flex-col flex-1 min-w-0 min-h-0 gap-[10px] p-[16px] ${look.c.editor}`}>
      {busy ? <div className={`shrink-0 h-[2px] ${look.ink ? 'bg-black' : 'bg-[#0e70c0]'}`} /> : null}
      <span className={`text-[11px] font-bold ${look.c.sideHead}`}>{changing ? 'ASK AI FOR A CHANGE' : 'ASK AI FOR A NEW SCENE'}</span>
      <span className={`text-[13px] leading-snug ${look.c.dim}`}>
        {changing
          ? 'What should change? The AI changes the scene as it is here, your unsaved edits included, and nothing is saved until you save its draft.'
          : 'What should the new scene show or do? Nothing is installed until you save the draft.'}
      </span>
      <textarea
        className={`flex-1 min-h-0 p-[8px] text-[13px] ${look.c.field}`}
        value={prompt}
        placeholder={changing ? 'Make the text bigger and add the date' : 'A clock with the weather in Brussels'}
        onChange={(e) => frameos.remember('prompt', String(e.target.value).slice(0, 2000))}
      />
      <div className="shrink-0 flex items-center gap-[8px]">
        <Button look={look} label={busy ? 'Asking…' : 'Ask'} primary off={busy} onClick={send} />
        <Button look={look} label="Cancel" off={busy} onClick={() => set(spot, { view: changing ? 'code' : 'list', note: '' })} />
        {busy ? <span className={`text-[12px] ${look.c.dim}`}>The AI is writing the scene and checking that it renders: a minute or two.</span> : null}
      </div>
    </div>
  )
}

// The file showing: the box that scrolls through all of it, its window of
// lines in a field beside their numbers. Where it is scrolled to is kept per
// file, and the box is told so (scrollTop) when another file opens.
function Editor({ look, work, file, area }) {
  const doc = docFor(work, file)
  const lang = kindOf(file).lang
  const n = doc.lines.length
  const at = `${work.key}\u0000${file}`
  const top = scrollsKept()[at] || 0
  const fit = Math.max(3, Math.ceil(area.height / ROW))
  const first = Math.max(0, Math.min(n - 1, Math.floor((top - PAD) / ROW)))
  slide(work, doc, first, fit)
  const numbers = []
  for (let i = doc.a; i < doc.b; i++) numbers.push(String(i + 1), <br />)
  const gutterW = Math.round(look.size * 0.6 * Math.max(3, String(n).length) + 26)
  const info = { lang, from: first, to: Math.min(n, first + fit), lines: n }
  const scrolled = (e) => {
    scrollsKept()[at] = e.scrollTop
    frameos.remember('scrolls', scrolls)
  }
  return {
    info,
    body: (
      <div
        className={`flex flex-col flex-1 min-h-0 overflow-y-auto ${MONO} text-[${look.size}px] ${look.c.editor}`}
        scrollTop={top}
        onScroll={scrolled}
      >
        <div className={`shrink-0 h-[${PAD + doc.a * ROW}px]`} />
        <div className="shrink-0 flex">
          <div className={`shrink-0 w-[${gutterW}px] pr-[18px] text-right whitespace-nowrap leading-[${ROW}px] ${look.c.gutter}`}>{numbers}</div>
          <textarea
            className={`flex-1 min-w-0 whitespace-nowrap overflow-x-auto leading-[${ROW}px] ${look.c.editor}`}
            value={doc.lines.slice(doc.a, doc.b).join('\n')}
            onChange={(e) => typed(work, doc, e.value)}
          >
            {colored(doc, lang, look)}
          </textarea>
        </div>
        <div className={`shrink-0 h-[${(n - doc.b) * ROW + 3 * ROW}px]`} />
      </div>
    ),
  }
}

// A scene (or the AI's draft) open: the workbench.
function Workbench({ app, look, spot, facts }) {
  const key = spot.draft ? DRAFT : spot.id
  const work = workFor(key)
  const busy = facts.busy
  const back = () => set(spot, { view: 'list', draft: false, note: '' })
  if (work.error) {
    return (
      <div className="flex flex-col flex-1 min-h-0">
        <div className={`flex flex-col flex-1 items-start gap-[12px] p-[16px] text-[13px] ${look.c.editor}`}>
          <span className={look.c.dim}>{work.error}</span>
          <Button look={look} label="Back to the scenes" onClick={back} />
        </div>
      </div>
    )
  }
  const file = work.order.includes(spot.file) ? spot.file : work.order[0]
  const changed = work.changed.length > 0
  const name = spot.draft ? (facts.draft && facts.draft.name) || 'New scene' : work.original.name || spot.id
  const summary = spot.draft && facts.draft ? facts.draft.summary : ''
  const asking = spot.view === 'ask' && facts.ask

  const save = (show) => {
    fold(work)
    const built = sceneOf(work.original, work.files)
    if (built.error) return set(spot, { note: built.error })
    const why = refusalOf(built.scene)
    if (why) return set(spot, { note: say(why) })
    // A scene new to the frame never takes its default from the owner.
    const known = (Array.isArray(app.frame.scenes) ? app.frame.scenes : []).some((s) => s && s.id === built.scene.id)
    if (!known) delete built.scene.default
    const r = code('save', { scene: built.scene, show })
    set(spot, r.ok ? { saving: { id: built.scene.id, show, draft: !!spot.draft }, note: '' } : { note: r.why })
  }
  const discard = () => {
    code('clear')
    dropWork()
    set(spot, { view: spot.id ? 'code' : 'list', draft: false, file: 'scene.json', note: '' })
  }

  // The room the code has: what the bars, the explorer and the AI's words leave.
  const sideW = look.wide ? look.activityW + look.sideW : 0
  const infoH = summary ? 38 : 0
  const area = {
    width: look.width - sideW,
    height: look.height - look.tabH - (look.wide ? 22 : 0) - look.statusH - infoH,
  }
  const editor = asking ? null : Editor({ look, work, file, area })
  const info = editor ? editor.info : null

  const kind = kindOf(file)
  const tab = look.wide ? (
    <div className={`shrink-0 flex items-center gap-[6px] h-[${look.tabH}px] px-[12px] text-[13px] ${look.c.tab}`}>
      <span className={`text-[10px] font-bold ${look.ink ? '' : kind.color}`}>{kind.badge}</span>
      <span className="whitespace-nowrap">{file.slice(file.indexOf('/') + 1)}</span>
      <span className={look.c.dim}>{work.changed.includes(file) ? '•' : ''}</span>
    </div>
  ) : (
    <select
      className={`flex-1 min-w-0 h-[26px] px-[8px] text-[13px] ${look.c.field}`}
      value={file}
      onChange={(e) => set(spot, { file: String(e.target.value) })}
    >
      {work.order.map((f) => (
        <option value={f} className={f === file ? look.c.rowOn : ''}>
          {work.changed.includes(f) ? `${f} •` : f}
        </option>
      ))}
    </select>
  )
  // The tab, then what goes for the whole scene (Ask AI, a draft's Discard,
  // Save). A narrow screen has no activity bar: its way back to the scenes is
  // first.
  const tabBar = asking ? null : (
    <div className={`shrink-0 flex items-center gap-[6px] h-[${look.tabH}px] pr-[8px] ${look.c.tabs} ${look.wide ? '' : 'pl-[8px]'}`}>
      {look.wide ? null : <Button look={look} label="‹" onClick={back} />}
      {tab}
      <span className="flex-1" />
      {facts.ask ? <Button look={look} label="Ask AI" off={!!busy} onClick={() => set(spot, { view: 'ask', note: '' })} /> : null}
      {spot.draft ? <Button look={look} label="Discard" off={!!busy} onClick={discard} /> : null}
      {facts.save ? <Button look={look} label="Save" primary={changed || spot.draft} off={!!busy || (!changed && !spot.draft)} onClick={() => save(false)} /> : null}
      {facts.save && spot.draft ? <Button look={look} label="Save & show" off={!!busy} onClick={() => save(true)} /> : null}
    </div>
  )
  const crumbs = look.wide ? (
    <div className={`shrink-0 flex items-center h-[22px] px-[14px] text-[12px] whitespace-nowrap overflow-hidden ${look.c.crumbs}`}>
      {[name, ...file.split('/')].join('  ›  ')}
    </div>
  ) : null
  const aiSaid = summary ? (
    <div className={`shrink-0 flex items-center h-[${infoH}px] px-[12px] text-[12px] ${look.c.info}`}>
      <span className="truncate">{`AI: ${summary}`}</span>
    </div>
  ) : null

  return (
    <div className="flex flex-col flex-1 min-h-0">
      <div className="flex flex-1 min-h-0">
        {look.wide ? <ActivityBar look={look} spot={spot} facts={facts} open /> : null}
        {look.wide ? <Explorer look={look} spot={spot} work={work} file={file} title={name} /> : null}
        {asking ? (
          <Ask look={look} spot={spot} facts={facts} work={work} />
        ) : (
          <div className={`flex flex-col flex-1 min-w-0 min-h-0 ${look.c.editor}`}>
            {tabBar}
            {crumbs}
            {aiSaid}
            {editor.body}
          </div>
        )}
      </div>
      <StatusBar
        look={look}
        draft={spot.draft}
        left={[spot.draft ? 'AI draft' : spot.id, ...(changed ? [`${work.changed.length} changed`] : [])]}
        right={
          info
            ? [`Ln ${info.from + 1}–${info.to} of ${info.lines}`, info.lang]
            : [busy === 'ask' ? 'Asking the AI…' : '']
        }
      />
    </div>
  )
}

// What came back since the last render: an answer from the AI, a save done.
function collect(spot, facts) {
  if (facts.busy) return
  if (spot.asking) {
    spot.asking = false
    if (facts.error) spot.note = say(facts.error)
    else if (facts.done === 'ask' && facts.draft) {
      dropWork()
      frameos.remember('prompt', '')
      set(spot, { view: 'code', draft: true, file: 'scene.json', note: '' })
    }
  }
  if (spot.saving) {
    const saving = spot.saving
    spot.saving = null
    if (facts.error) spot.note = say(facts.error)
    else if (facts.done === 'save') {
      spot.note = saving.show ? 'Saved. The frame shows it once it arrives.' : 'Saved. The frame gets it with its next push.'
      if (saving.draft) {
        code('clear')
        set(spot, { draft: false, id: saving.id })
      }
      // Read again from what the frame holds, once the push lands.
      dropWork(true)
    }
  }
}

export function get(app, context) {
  const look = lookOf(app, context)
  const spot = readSpot(app)
  opened(app, spot)
  const read = code('read')
  const facts = read.ok ? read.value : null
  let page
  if (!read.ok || !facts) {
    page = (
      <div className={`flex flex-col flex-1 gap-[8px] p-[24px] ${look.c.editor}`}>
        <span className="text-[20px] font-light">Code editor</span>
        <span className={`text-[13px] leading-snug ${look.c.dim}`}>
          {read.ok
            ? "The code editor needs the frame's settings on its screen, and this frame has them off (or no host to read scenes from)."
            : read.why}
        </span>
      </div>
    )
  } else {
    collect(spot, facts)
    if (facts.previewOnly && !spot.previewNoted) {
      spot.previewNoted = true
      spot.note = 'In the preview the code is read only: saving and the AI are on a frame.'
    }
    const open = spot.id || spot.draft
    const asking = spot.view === 'ask' && facts.ask
    page =
      open && (spot.view === 'code' || asking) ? (
        <Workbench app={app} look={look} spot={spot} facts={facts} />
      ) : (
        <Home app={app} look={look} spot={spot} facts={facts} asking={asking} />
      )
  }
  saveSpot(spot)
  return (
    <div className={`relative flex flex-col w-full h-full text-[${look.size}px] ${look.c.editor}`}>
      {page}
      <Toast look={look} spot={spot} />
    </div>
  )
}

