import { get, filesOf, sceneOf, tokensOf, refusalOf } from './app'

const SCENE = {
  id: 'clock',
  name: 'Clock',
  settings: { execution: 'interpreted' },
  fields: [],
  nodes: [
    { id: 'render', type: 'event', data: { keyword: 'render' } },
    { id: 'app', type: 'app', data: { keyword: 'clockFace', config: {} } },
    { id: 'c1', type: 'code', data: { codeJS: 'return new Date().getHours()' } },
  ],
  edges: [],
  apps: {
    clockFace: {
      name: 'Clock face',
      version: '1.0.0',
      sources: {
        'config.json': '{\n  "name": "Clock face",\n  "version": "1.0.0"\n}\n',
        'app.tsx': "export function get() {\n  return <div>12:00</div>\n}\n",
      },
    },
  },
}

const FACTS = { busy: '', error: '', done: '', draft: null, ask: true, save: true }

function texts(node: any, into: string[] = []): string[] {
  if (node === null || node === undefined || node === false) return into
  if (typeof node === 'string' || typeof node === 'number') into.push(String(node))
  else if (Array.isArray(node)) node.forEach((child) => texts(child, into))
  else if (node.props) texts(node.props.children, into)
  return into
}

function find(node: any, test: (n: any) => boolean): any {
  if (!node || typeof node !== 'object') return null
  if (Array.isArray(node)) {
    for (const child of node) {
      const hit = find(child, test)
      if (hit) return hit
    }
    return null
  }
  if (test(node)) return node
  if (typeof node.type === 'function') return find(node.type(node.props), test)
  return node.props ? find(node.props.children, test) : null
}

// The tree with every component rendered, so its texts and handlers show.
function expand(node: any): any {
  if (!node || typeof node !== 'object') return node
  if (Array.isArray(node)) return node.map(expand)
  if (typeof node.type === 'function') return expand(node.type(node.props))
  if (!node.props) return node
  return { ...node, props: { ...node.props, children: expand(node.props.children) } }
}

const render = (app: any) => expand(get(app, makeContext()))
// Code is drawn with non-breaking spaces, so its indentation stays.
const screen = (app: any) => texts(render(app)).join('').replace(/\u00a0/g, ' ')
const button = (app: any, label: string) =>
  find(render(app), (n) => n.props && n.props.onClick && texts(n.props.children).join('') === label)
const tap = (app: any, label: string) => {
  const hit = button(app, label)
  if (!hit) throw new Error('no button ' + label + ' in ' + screen(app))
  hit.props.onClick({})
}

function host(sources: Record<string, any>, facts: any = FACTS) {
  return mock.code((op: string, arg: any) => {
    if (op === 'read') return facts
    if (op === 'source') return sources[arg] || null
    if (op === 'draft') return sources['\u0001draft'] || null
    return true
  })
}

describe('the files of a scene', () => {
  it('splits a scene into files and puts it back the same', () => {
    const { files, order } = filesOf(SCENE)
    expect(order).toEqual(['scene.json', 'clockFace/config.json', 'clockFace/app.tsx', 'code/c1.js'])
    expect(files['scene.json']).not.toContain('getHours')
    expect(files['scene.json']).not.toContain('<div>')
    expect(files['code/c1.js']).toBe('return new Date().getHours()')
    const back = sceneOf(SCENE, files)
    expect(back.scene).toEqual(SCENE)
  })

  it('takes edits back into the scene, config.json included', () => {
    const { files } = filesOf(SCENE)
    files['clockFace/app.tsx'] = 'export function get() { return <div>13:00</div> }'
    files['clockFace/config.json'] = '{"name": "Clock face", "version": "1.1.0"}'
    files['code/c1.js'] = 'return 1'
    const back = sceneOf(SCENE, files).scene
    expect(back.apps.clockFace.sources['app.tsx']).toContain('13:00')
    expect(back.apps.clockFace.version).toBe('1.1.0')
    expect(back.nodes[2].data.codeJS).toBe('return 1')
  })

  it('says where a JSON file does not parse', () => {
    const { files } = filesOf(SCENE)
    files['scene.json'] = '{ "id": '
    expect(sceneOf(SCENE, files).error).toContain('scene.json')
    const again = filesOf(SCENE).files
    again['clockFace/config.json'] = 'nope'
    expect(sceneOf(SCENE, again).error).toContain('clockFace/config.json')
  })
})

describe('what no frame takes', () => {
  it('refuses a built-in id and a compiled scene, before the frame does', () => {
    expect(refusalOf(SCENE)).toBe('')
    expect(refusalOf({ ...SCENE, id: 'system/sceneSwitcher' })).toBe('invalid_scene')
    expect(refusalOf({ ...SCENE, id: '' })).toBe('invalid_scene')
    expect(refusalOf({ ...SCENE, settings: { execution: 'compiled' } })).toBe('scene_requires_compilation')
  })
})

describe('the code, colored', () => {
  it('reads keywords, strings, numbers, calls and comments', () => {
    const { tokens } = tokensOf("const x = fetch('a', 42) // why", 'TypeScript', false)
    const kinds = tokens.filter((t: any) => t.t.trim()).map((t: any) => t.k + ':' + t.t.trim())
    expect(kinds).toEqual(['k:const', 'v:x', 'p:=', 'f:fetch', 'p:(', "s:'a'", 'p:,', 'n:42', 'p:)', 'm:// why'])
  })

  it('carries a block comment over lines, and reads JSON keys', () => {
    const one = tokensOf('/* one', 'JavaScript', false)
    expect(one.open).toBe(true)
    const two = tokensOf('two */ return 1', 'JavaScript', one.open).tokens
    expect(two[0]).toEqual({ t: 'two */', k: 'm' })
    expect(two.find((p: any) => p.t === 'return').k).toBe('c')
    const json = tokensOf('{ "id": "clock" }', 'JSON', false).tokens
    expect(json.find((p: any) => p.t === '"id"').k).toBe('v')
    expect(json.find((p: any) => p.t === '"clock"').k).toBe('s')
  })
})

// A file of `n` lines, each saying its number.
const long = (n: number) => Array.from({ length: n }, (_, i) => `const line${i + 1} = ${i + 1} // ${i + 1}`).join('\n')

const LONG = {
  ...SCENE,
  apps: { clockFace: { ...SCENE.apps.clockFace, sources: { ...SCENE.apps.clockFace.sources, 'app.tsx': long(2000) } } },
}

// The file's box that scrolls, and its field.
const scroller = (app: any) => find(render(app), (n) => n.props && n.props.onScroll)
const field = (app: any) => find(render(app), (n) => n.type === 'textarea')
const lineCount = (text: string) => text.split('\n').length
const openApp = (app: any) =>
  find(render(app), (n) => n.props && n.props.onClick && texts(n.props.children).includes('app.tsx')).props.onClick({})

describe('the code editor', () => {
  it('lists the frame scenes and opens one as files', () => {
    const app = makeApp({ frame: { scenes: [{ id: 'clock', name: 'Clock' }] } })
    host({ clock: SCENE })
    expect(screen(app)).toContain('Clock')
    find(render(app), (n) => n.props && n.props.onClick && texts(n.props.children).includes('Clock')).props.onClick({})
    const shown = screen(app)
    expect(shown).toContain('scene.json')
    expect(shown).toContain('"id": "clock",')
  })

  it('lists the scenes by category, Other last', () => {
    const app = makeApp({
      frame: {
        scenes: [
          { id: 'w', name: 'Weather', category: 'Weather' },
          { id: 'n', name: 'Notes' },
          { id: 'c', name: 'Clock', category: 'Clocks' },
          { id: 'k', name: 'Kitchen clock', category: 'clocks' },
        ],
      },
    })
    host({})
    // The groups by name, sorted whatever the case (the desktops' rule), each
    // scene under its own, Other last.
    expect(screen(app)).toContain('ClocksClockclocksKitchen clockWeatherWeatherOtherNotes')
  })

  it('opens on the scene the scene settings asked for', () => {
    const app = makeApp({ frame: { scenes: [{ id: 'clock', name: 'Clock' }] }, state: { open: 'clock' } })
    host({ clock: SCENE })
    expect(screen(app)).toContain('"name": "Clock",')
    expect(app.state.open).toBe('')
  })

  it('types into a file and saves the scene back', () => {
    const app = makeApp({ frame: { scenes: [{ id: 'clock', name: 'Clock' }] }, state: { open: 'clock' } })
    const code = host({ clock: SCENE })
    screen(app)
    // The explorer: the app's folder and its files. A short file is all in the field.
    openApp(app)
    expect(field(app).props.value).toBe(SCENE.apps.clockFace.sources['app.tsx'])
    const text = 'export function get() {\n  return <div>13:00</div>\n}\n'
    field(app).props.onChange({ value: text, target: { value: text } })
    expect(field(app).props.value).toBe(text)
    expect(screen(app)).toContain('1 changed')
    tap(app, 'Save')
    const saved = code.calls.find((call: any[]) => call[0] === 'save')
    expect(saved[1].show).toBe(false)
    expect(saved[1].scene.id).toBe('clock')
    expect(saved[1].scene.apps.clockFace.sources['app.tsx']).toContain('13:00')
  })

  it('colors the field: its spans spell its value', () => {
    const app = makeApp({ frame: { scenes: [{ id: 'clock', name: 'Clock' }] }, state: { open: 'clock' } })
    host({ clock: SCENE })
    screen(app)
    openApp(app)
    const area = field(app)
    expect(texts(area.props.children).join('')).toBe(area.props.value)
    const kinds = (area.props.children as any[]).filter((c) => c && c.props).map((c) => c.props.className + ':' + texts(c.props.children).join(''))
    expect(kinds).toContain('text-[#569cd6]:function')
    expect(kinds).toContain('text-[#c586c0]:return')
    // On e-paper: black on white, no spans.
    const ink = makeApp({ frame: { paper: true, scenes: [{ id: 'clock', name: 'Clock' }] }, state: { open: 'clock' } })
    screen(ink)
    openApp(ink)
    expect(field(ink).props.children).toBeFalsy()
  })

  it('holds a long file as a window of lines that slides as it scrolls', () => {
    const app = makeApp({ frame: { scenes: [{ id: 'clock', name: 'Clock' }] }, state: { open: 'clock' } })
    host({ clock: LONG })
    screen(app)
    openApp(app)
    // At the top: the screen and one below it, not 2,000 lines.
    let value = field(app).props.value
    expect(value.startsWith('const line1 = 1')).toBe(true)
    expect(lineCount(value)).toBeLessThan(120)
    expect(scroller(app).props.scrollTop).toBe(0)
    // Scrolled to line 1,001: the window has it, and spacers stand for the rest.
    scroller(app).props.onScroll({ scrollTop: 4 + 1000 * 19 })
    value = field(app).props.value
    expect(value).toContain('const line1001 = 1001')
    expect(value).not.toContain('const line1 = 1\n')
    expect(screen(app)).toContain('Ln 1001')
    // A little further: it grows at the end only, so a caret on its text stays.
    const before = field(app).props.value
    scroller(app).props.onScroll({ scrollTop: 4 + 1010 * 19 })
    const after = field(app).props.value
    expect(after.startsWith(before) || after.endsWith(before)).toBe(true)
  })

  it('keeps what was typed when the window moves away and back, and saves it', () => {
    const app = makeApp({ frame: { scenes: [{ id: 'clock', name: 'Clock' }] }, state: { open: 'clock' } })
    const code = host({ clock: LONG })
    screen(app)
    openApp(app)
    scroller(app).props.onScroll({ scrollTop: 4 + 1500 * 19 })
    const value = field(app).props.value
    const edited = value.replace('const line1501 = 1501', 'const line1501 = 15010')
    field(app).props.onChange({ value: edited, target: { value: edited } })
    scroller(app).props.onScroll({ scrollTop: 0 }) // away
    expect(field(app).props.value).not.toContain('15010')
    scroller(app).props.onScroll({ scrollTop: 4 + 1500 * 19 }) // and back
    expect(field(app).props.value).toContain('const line1501 = 15010')
    tap(app, 'Save')
    const saved = code.calls.find((call: any[]) => call[0] === 'save')[1]
    const text = saved.scene.apps.clockFace.sources['app.tsx']
    expect(lineCount(text)).toBe(2000)
    expect(text.split('\n')[1500]).toBe('const line1501 = 15010 // 1501')
  })

  it('stays where it was in a file once a save is read back', () => {
    const app = makeApp({ frame: { scenes: [{ id: 'clock', name: 'Clock' }] }, state: { open: 'clock' } })
    const facts: any = { ...FACTS }
    host({ clock: LONG }, facts)
    screen(app)
    openApp(app)
    scroller(app).props.onScroll({ scrollTop: 4 + 700 * 19 })
    const value = field(app).props.value
    field(app).props.onChange({ value: 'x' + value, target: { value: 'x' + value } })
    tap(app, 'Save')
    Object.assign(facts, { done: 'save' })
    expect(screen(app)).toContain('Saved.')
    expect(scroller(app).props.scrollTop).toBe(4 + 700 * 19)
    expect(field(app).props.value).toContain('const line701 = 701')
  })

  it('opens each file where it was left', () => {
    const app = makeApp({ frame: { scenes: [{ id: 'clock', name: 'Clock' }] }, state: { open: 'clock' } })
    host({ clock: LONG })
    screen(app)
    openApp(app)
    scroller(app).props.onScroll({ scrollTop: 500 })
    expect(scroller(app).props.scrollTop).toBe(500)
    find(render(app), (n) => n.props && n.props.onClick && texts(n.props.children).includes('scene.json')).props.onClick({})
    expect(scroller(app).props.scrollTop).toBe(0)
    openApp(app)
    expect(scroller(app).props.scrollTop).toBe(500)
  })

  it('asks the AI for a change with the scene as it is, and opens the draft', () => {
    const app = makeApp({ frame: { scenes: [{ id: 'clock', name: 'Clock' }] }, state: { open: 'clock' } })
    const sources: Record<string, any> = { clock: SCENE }
    const facts: any = { ...FACTS }
    const code = host(sources, facts)
    screen(app)
    tap(app, 'Ask AI')
    find(render(app), (n) => n.type === 'textarea').props.onChange({ value: 'Bigger', target: { value: 'Bigger' } })
    tap(app, 'Ask')
    const asked = code.calls.find((call: any[]) => call[0] === 'ask')
    expect(asked[1].prompt).toBe('Bigger')
    expect(asked[1].scene.id).toBe('clock')
    // The plane answers: a draft.
    sources['\u0001draft'] = { ...SCENE, name: 'Big clock' }
    Object.assign(facts, { done: 'ask', draft: { id: 'clock', name: 'Big clock', summary: 'A bigger clock.' } })
    const shown = screen(app)
    expect(shown).toContain('Big clock')
    expect(shown).toContain('AI draft')
    expect(shown).toContain('A bigger clock.')
    tap(app, 'Save & show')
    const saved = code.calls.find((call: any[]) => call[0] === 'save')[1]
    expect(saved.show).toBe(true)
    // The frame holds the clock: a change to it keeps what it is.
    expect(saved.scene.id).toBe('clock')
  })

  it('takes the default mark off a scene new to the frame', () => {
    const app = makeApp({ frame: { scenes: [{ id: 'clock', name: 'Clock' }] } })
    const facts: any = { ...FACTS, done: 'ask', draft: { id: 'made', name: 'Made', summary: '' } }
    const code = host({ '\u0001draft': { ...SCENE, id: 'made', name: 'Made', default: true } }, facts)
    tap(app, 'New scene with AI')
    find(render(app), (n) => n.type === 'textarea').props.onChange({ value: 'A clock', target: { value: 'A clock' } })
    tap(app, 'Ask')
    tap(app, 'Save')
    const saved = code.calls.find((call: any[]) => call[0] === 'save')[1]
    expect(saved.scene.id).toBe('made')
    expect('default' in saved.scene).toBe(false)
  })

  it('says why the AI refused', () => {
    const app = makeApp({ frame: { scenes: [] } })
    const facts: any = { ...FACTS }
    host({}, facts)
    tap(app, 'New scene with AI')
    find(render(app), (n) => n.type === 'textarea').props.onChange({ value: 'A clock', target: { value: 'A clock' } })
    tap(app, 'Ask')
    Object.assign(facts, { error: 'ai_unavailable' })
    expect(screen(app)).toContain('no AI to ask')
  })

  it('says when the settings on the screen are off', () => {
    const app = makeApp({ frame: { scenes: [] } })
    mock.code(() => null)
    expect(screen(app)).toContain("frame's settings on its screen")
  })
})
